<?php
/** Plugin Name: TEMP PS S1699 petshop-paieska v1.0 deploy */
add_action('wp_loaded', function(){
  $f=(isset($_GET['ps_s1699'])?$_GET['ps_s1699']:''); if(!in_array($f,array('1','2','9'),true)) return;
  header('Content-Type: application/json; charset=utf-8');
  $o=array('v'=>'S1699 mc','faze'=>$f); $t=WP_CONTENT_DIR.'/mu-plugins/petshop-paieska.php';
  try{
    if($f==='1'){
      if(file_exists($t)) throw new Exception('failas jau yra');
      if(class_exists('Petshop_Paieska')) throw new Exception('klasė užimta');
      $src=base64_decode(''); if(md5($src)!=='b4f486f31b847685a5d801e8f9642752') throw new Exception('md5');
      $tok=token_get_all($src,TOKEN_PARSE); $o['tokenu']=count($tok);
      if(file_put_contents($t,$src)!==strlen($src)) throw new Exception('rasymas');
      $r=wp_remote_get(home_url('/?ps_hb='.time()),array('timeout'=>20)); $c=is_wp_error($r)?0:wp_remote_retrieve_response_code($r); $o['heartbeat']=$c;
      if($c>=500||$c===0){ rename($t,$t.'.off_s1699'); $o['ROLLBACK']=1; }
      $r2=wp_remote_get(home_url('/?s=expulsion&post_type=product'),array('timeout'=>25)); $o['paieskos_puslapis']=is_wp_error($r2)?'ERR':wp_remote_retrieve_response_code($r2);
      $o['md5']=file_exists($t)?md5_file($t):null;
    } elseif($f==='9'){ if(file_exists($t)) rename($t,$t.'.off_s1699'); $o['isjungta']=!file_exists($t); }
    else {
      $o['klase']=class_exists('Petshop_Paieska'); $o['filtras']=has_filter('posts_search',array('Petshop_Paieska','posts_search'));
      foreach(array('expulsion','kiauliena su zirneis','jesera festivalis','katės pieno pakaitalas','exclusion','miamor') as $s){ $q=new WP_Query(array('s'=>$s,'post_type'=>'product','post_status'=>'publish','posts_per_page'=>2,'fields'=>'ids')); $o['t'][$s]=$q->found_posts; }
      // Flatsome live search ajax
      $r=wp_remote_post(admin_url('admin-ajax.php'),array('timeout'=>25,'body'=>array('action'=>'flatsome_ajax_search_products','query'=>'expulsion'))); $o['flatsome_ajax']=is_wp_error($r)?'ERR':array(wp_remote_retrieve_response_code($r),mb_substr(wp_remote_retrieve_body($r),0,300));
      $r=wp_remote_get(home_url('/?s=kiauliena+su+zirneis&post_type=product'),array('timeout'=>25)); $b=wp_remote_retrieve_body($r); $o['puslapis_zirneis']=array(wp_remote_retrieve_response_code($r),substr_count($b,'class="product-small'),preg_match('/(\d+)\s*rezultat/u',$b,$m)?$m[0]:'?');
    }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
});
